/**
 * The prayer city catalogue (wiki Epic 21 §3, E21-D3): GeoNames cities of 15,000 people or more
 * (CC BY 4.0), generated by scripts/build-prayer-cities.ts into cities.data.ts. Apps bundle the
 * same ids, so a city id is the only location value that ever reaches the server.
 *
 * Lookups scan the packed text for one id instead of parsing every city into objects: one
 * indexOf over about 1.8 MB, done only on a prayer-cache miss or a city-name lookup.
 */
import { PRAYER_CITIES_TSV } from './cities.data';

export interface PrayerCity {
	id: string;
	latitude: number;
	longitude: number;
	country: string;
	timeZone: string;
	name: string;
}

export const CITY_ID = /^[1-9][0-9]{0,9}$/;

function parse(line: string): PrayerCity | null {
	const [id, lat, lon, country, timeZone, name] = line.split('\t');
	if (!id || !timeZone) return null;
	return { id, latitude: Number(lat), longitude: Number(lon), country, timeZone, name };
}

export function findCity(id: string, data = PRAYER_CITIES_TSV): PrayerCity | null {
	if (!CITY_ID.test(id)) return null;
	const at = data.indexOf(`\n${id}\t`);
	if (at < 0) return null;
	const end = data.indexOf('\n', at + 1);
	return parse(data.slice(at + 1, end < 0 ? undefined : end));
}
